operation.add:
// AI Admin: the AI connection (MCP, OAuth, upload links) keeps working, the storefront stays closed
if (strpos($route, 'extension/module/mcp_server') === 0) {
	return;
}

// its short addresses (/mcp, /mcp-oauth-token, /.well-known/..., the secret one) are SEO URLs, resolved only after this check;
// every part must be one of them - /mcp/<a page keyword> would open that page of the closed store
if (!empty($this->request->get['_route_'])) {
	$mcp_parts = array_values(array_unique(array_filter(explode('/', (string)$this->request->get['_route_']), 'strlen')));
	$mcp_in = implode(', ', array_map(function ($p) { return "'" . $this->db->escape($p) . "'"; }, $mcp_parts));
	$mcp_alias = $mcp_parts ? $this->db->query("SELECT COUNT(DISTINCT `keyword`) AS n FROM `" . DB_PREFIX . "seo_url` WHERE `keyword` IN (" . $mcp_in . ") AND `query` LIKE 'extension/module/mcp_server/%'") : null;

	if ($mcp_alias && (int)$mcp_alias->row['n'] === count($mcp_parts)) {
		return;
	}
}

// AI Admin: the AI sends JSON (no form fields), so SEO Pro took it for a page view and redirected /mcp to /mcp/ or
// /mcp.html - the client repeats a redirect as GET and the connection breaks (HTTP 405)
if (isset($this->request->get['route']) && strpos((string)$this->request->get['route'], 'extension/module/mcp_server') === 0)
    return;
